<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { RouterLink, useRoute } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { get, post } from '../api/client';
import { session } from '../api/session';
import { Button, Card, Field, Input, Select, EmptyState } from '../components/ui';
interface Policy { id: number; siteId: number; name: string; period: string; basis: string; amountUsd: string; warningPercent: number; channelId: string | null; model: string | null; enabled: boolean; notify: boolean; version: number }
interface Draft { name: string; period: string; basis: string; amountUsd: number | string; warningPercent: number | string; channelId: string; model: string; enabled: boolean; notify: boolean }
interface Report { policy: { name: string; amountUsd: string; basis: string; version: number }; observedUsd: string | null; observedPercent: number | null; status: string; records: number; pricedRecords: number; completeDays: number; missingDays: number; stale: boolean; latestCollectionAt: string | null; evaluatedAt: string; window: { from: string; to: string; endExclusive: string; days: string[]; timezone: string }; days: { day: string; scanStatus: string; records: number; pricedRecords: number; observedUsd: string | null; sourceScope: string | null }[] }
interface Event { id: number; policyVersion: number; periodStart: string; level: number; evidence: Report; acknowledgedAt: string | null; acknowledgement: string | null; createdAt: string }
const base = '/api/services/budgets', route = useRoute(), { locale } = useI18n();
const l = (zh: string, en: string) => locale.value.startsWith('zh') ? zh : en;
const labels: Record<string, [string, string]> = { day: ['每日', 'Daily'], week: ['每周（周一开始）', 'Weekly (Monday start)'], month: ['每月', 'Monthly'], charge: ['记录扣费', 'Recorded charges'], supplierCost: ['记录上游成本', 'Recorded supplier cost'], no_evidence: ['暂无金额证据', 'No priced evidence'], observed_below_threshold: ['已观测金额低于提醒线', 'Observed amount below warning'], warning: ['已观测金额达到提醒线', 'Observed warning threshold reached'], exceeded: ['已观测金额达到预算', 'Observed budget reached'], complete: ['本轮读取完整', 'Scan complete'], partial: ['部分读取', 'Partial scan'], missing: ['尚无采集', 'No collection'], error: ['采集失败', 'Collection failed'], changed: ['来源变化', 'Source changed'], unsupported: ['接口不兼容', 'Unsupported source'], pending: ['待采集', 'Pending'], 'consumption-only': ['消费日志', 'Consumption logs'], 'consume-and-error-logs': ['消费与错误日志', 'Consumption and error logs'] };
const label = (key: string) => labels[key] ? l(...labels[key]) : key;
const options = (keys: string[]) => keys.map(value => ({ value, label: label(value) }));
const sites = ref<{ id: number; label: string }[]>([]), siteId = ref<string | number | null>(null), items = ref<Policy[]>([]), selected = ref<Policy | null>(null);
const canManage = ref(false), busy = ref(false), editing = ref(false), error = ref(''), notice = ref(''), intervalMs = ref(0);
const report = ref<Report | null>(null), events = ref<Event[]>([]), hasMore = ref(false), notes = ref<Record<number, string>>({});
const blank = (): Draft => ({ name: '', period: 'day', basis: 'charge', amountUsd: 100, warningPercent: 80, channelId: '', model: '', enabled: true, notify: false });
const draft = ref<Draft>(blank());
const body = () => ({ ...draft.value, amountUsd: Number(draft.value.amountUsd), warningPercent: Number(draft.value.warningPercent), channelId: draft.value.channelId.trim() || null, model: draft.value.model.trim() || null });
const fromPolicy = (p: Policy): Draft => ({ name: p.name, period: p.period, basis: p.basis, amountUsd: p.amountUsd, warningPercent: p.warningPercent, channelId: p.channelId ?? '', model: p.model ?? '', enabled: p.enabled, notify: p.notify });
const dirty = computed(() => JSON.stringify(draft.value) !== JSON.stringify(selected.value ? fromPolicy(selected.value) : blank()));
const number = (value: number | string | null | undefined) => value == null ? '—' : Number(value).toLocaleString(undefined, { maximumFractionDigits: 6 });
const progress = computed(() => Math.min(100, Math.max(0, report.value?.observedPercent ?? 0)));
async function action(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn(); } catch (e) { error.value = String(e); } finally { busy.value = false; } }
function discard() { return !dirty.value || window.confirm(l('放弃尚未保存的预算修改？', 'Discard unsaved budget changes?')); }
async function list() { if (!siteId.value) return; const r = await get<{ items: Policy[]; canManage: boolean; intervalMs: number }>(`${base}?siteId=${siteId.value}`); items.value = r.items; canManage.value = r.canManage; intervalMs.value = r.intervalMs; }
async function loadReport() { if (!selected.value) return; const [r, e] = await Promise.all([get<{ report: Report }>(`${base}/${selected.value.id}/report`), get<{ items: Event[]; hasMore: boolean }>(`${base}/${selected.value.id}/events`)]); report.value = r.report; events.value = e.items; hasMore.value = e.hasMore; }
async function chooseSite(value: string | number | null) { if (busy.value || !discard()) return; siteId.value = value; selected.value = null; draft.value = blank(); editing.value = false; report.value = null; events.value = []; await action(list); }
onMounted(() => void action(async () => { const r = await get<{ sites: typeof sites.value }>('/api/services/catalog'); sites.value = r.sites; siteId.value = r.sites.find(s => String(s.id) === route.query.site)?.id ?? r.sites[0]?.id ?? null; await list(); }));
async function open(p: Policy) { if (!discard()) return; await action(async () => { selected.value = p; draft.value = fromPolicy(p); editing.value = false; notes.value = {}; await loadReport(); }); }
function create() { if (!discard()) return; selected.value = null; draft.value = blank(); report.value = null; events.value = []; editing.value = true; }
async function save() { await action(async () => {
  const r = selected.value ? await post<{ item: Policy }>(`${base}/${selected.value.id}`, { ...body(), version: selected.value.version }) : await post<{ item: Policy }>(base, { ...body(), siteId: Number(siteId.value) });
  selected.value = r.item; draft.value = fromPolicy(r.item); editing.value = false; await list(); await loadReport(); notice.value = l('预算策略已保存。此策略仅观测与提醒，不修改引擎限额。', 'Budget policy saved. It observes and alerts without changing engine limits.');
}); }
async function pause() { if (!selected.value) return; await action(async () => { const p = selected.value!; const r = await post<{ item: Policy }>(`${base}/${p.id}`, { ...fromPolicy(p), amountUsd: Number(p.amountUsd), channelId: p.channelId, model: p.model, version: p.version, enabled: !p.enabled }); selected.value = r.item; draft.value = fromPolicy(r.item); await list(); await loadReport(); }); }
async function evaluate() { if (!selected.value) return; await action(async () => { const r = await post<{ report: Report; eventCreated: boolean }>(`${base}/${selected.value!.id}/evaluate`, {}); report.value = r.report; await loadReport(); notice.value = r.eventCreated ? l('已记录新的阈值事件；若启用通知，将按站长通知偏好发送。', 'A new threshold event was recorded. Enabled notifications follow the owner’s preferences.') : l('检查完成，没有新增阈值事件。', 'Checked. No new threshold event.'); }); }
async function acknowledge(event: Event) { if (!selected.value) return; await action(async () => { await post(`${base}/${selected.value!.id}/events/${event.id}/acknowledge`, { note: notes.value[event.id] ?? '' }); await loadReport(); notice.value = l('已记录复核说明。确认提醒不会改变预算或用量。', 'Review recorded. Acknowledging does not change the budget or usage.'); }); }
async function moreEvents() { if (!selected.value || !events.value.length) return; await action(async () => { const r = await get<{ items: Event[]; hasMore: boolean }>(`${base}/${selected.value!.id}/events?beforeId=${events.value.at(-1)!.id}`); events.value.push(...r.items); hasMore.value = r.hasMore; }); }
async function exportCsv() { if (!selected.value) return; await action(async () => { const workspace = localStorage.getItem('rp-workspace'); const r = await fetch(`${base}/${selected.value!.id}/report.csv`, { credentials: 'same-origin', headers: workspace ? { 'x-workspace-id': workspace } : {} }); if (!r.ok) throw new Error(`HTTP ${r.status}`); const url = URL.createObjectURL(await r.blob()), a = document.createElement('a'); a.href = url; a.download = 'observed-budget.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }); }
</script>
<template>
  <div class="rp-page space-y-5">
    <RouterLink v-if="session.isRoot.value" :to="{ path: '/risk', query: siteId ? { site: String(siteId) } : {}, hash: '#native-quotas' }" class="inline-block text-sm text-accent">{{ l('配置引擎用户限额（与观测预算独立）', 'Configure engine user quotas (independent of observation budgets)') }}</RouterLink>
    <div><p class="text-xs uppercase tracking-widest text-accent">BUDGET OBSERVATIONS</p><h1 class="mt-1 text-xl font-semibold">{{ l('预算与阈值提醒', 'Budgets and threshold alerts') }}</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-muted">{{ l('按站点、渠道或模型跟踪已有日志中的金额。无额外模型探测；采集缺口会明确显示，预算策略不会自动停用渠道或修改引擎限额。', 'Track existing log amounts by site, channel or model without model probes. Collection gaps remain visible. Budget policies do not disable channels or change engine limits.') }}</p></div>
    <p v-if="error" role="alert" class="rounded border border-red/30 bg-red/10 p-3 text-sm text-red">{{ error }}</p><p v-if="notice" role="status" class="text-sm text-accent">{{ notice }}</p>
    <EmptyState v-if="!sites.length && !busy" :title="l('先接入一个站点', 'Connect a site to begin')" />
    <template v-if="sites.length">
      <Field :label="l('当前站点', 'Current site')"><Select :model-value="siteId" :disabled="busy" :options="sites.map(s => ({ value: s.id, label: s.label }))" @update:model-value="chooseSite" /></Field>
      <p class="text-xs text-muted">{{ intervalMs ? l(`后台每 ${Math.max(1, Math.round(intervalMs / 60000))} 分钟轮转检查，每轮最多 5 条策略。`, `Background checks rotate every ${Math.max(1, Math.round(intervalMs / 60000))} minutes, up to 5 policies per pass.`) : l('后台检查已关闭，可手动读取已有证据。', 'Background checks are disabled. Existing evidence can be checked manually.') }} · {{ l('日历周期：北京时间', 'Calendar periods: Asia/Shanghai') }}</p>
      <div class="grid items-start gap-5 xl:grid-cols-[minmax(250px,1fr)_minmax(0,2fr)]">
        <Card class="min-w-0 [&>div]:space-y-3"><Button v-if="canManage" :disabled="busy" @click="create">{{ l('新建预算', 'New budget') }}</Button><p v-if="!items.length && !busy" class="text-sm text-muted">{{ l('暂无预算策略。', 'No budget policies.') }}</p><button v-for="p in items" :key="p.id" :disabled="busy" class="block w-full rounded-lg border border-border p-3 text-left hover:border-accent disabled:opacity-50" :class="selected?.id === p.id ? 'border-accent bg-accent/5' : ''" @click="open(p)"><span class="block break-words text-sm font-medium">{{ p.name }}</span><span class="mt-1 block text-xs text-muted">{{ number(p.amountUsd) }} USD · {{ label(p.period) }} · {{ p.enabled ? l('观测中', 'Observing') : l('已暂停', 'Paused') }}</span></button></Card>
        <div v-if="selected || editing" class="min-w-0 space-y-4">
          <Card v-if="editing" class="[&>div]:space-y-4"><h2 class="font-semibold">{{ selected ? l('修改预算策略', 'Edit budget policy') : l('创建预算策略', 'Create budget policy') }}</h2><form class="space-y-4" @submit.prevent="save"><fieldset :disabled="busy || !canManage" class="min-w-0 space-y-4">
            <Field :label="l('预算名称', 'Budget name')" required><Input v-model="draft.name" minlength="3" maxlength="120" required /></Field>
            <div class="grid gap-3 sm:grid-cols-2"><Field :label="l('预算周期', 'Period')"><Select v-model="draft.period" :options="options(['day', 'week', 'month'])" /></Field><Field :label="l('金额口径', 'Amount basis')"><Select v-model="draft.basis" :options="options(['charge', 'supplierCost'])" /></Field><Field :label="l('预算金额（USD）', 'Budget (USD)')" required><Input v-model="draft.amountUsd" type="number" min="0.000001" max="1000000000" step="0.000001" required /></Field><Field :label="l('预警阈值（%）', 'Warning threshold (%)')" required><Input v-model="draft.warningPercent" type="number" min="1" max="99" step="1" required /></Field></div>
            <div class="grid gap-3 sm:grid-cols-2"><Field :label="l('渠道编号（可选）', 'Channel ID (optional)')" :hint="l('留空覆盖全部渠道；填写时精确匹配日志中的编号。', 'Blank includes all channels; otherwise matches the exact log ID.')"><Input v-model="draft.channelId" maxlength="256" /></Field><Field :label="l('模型名称（可选）', 'Model name (optional)')" :hint="l('留空覆盖全部模型；与渠道条件同时生效。', 'Blank includes all models. Combined with the channel filter.')"><Input v-model="draft.model" maxlength="256" /></Field></div>
            <label class="flex items-start gap-2 text-sm"><input v-model="draft.enabled" type="checkbox" class="mt-1" /><span>{{ l('启用预算观测', 'Enable budget observations') }}</span></label><label class="flex items-start gap-2 text-sm"><input v-model="draft.notify" type="checkbox" class="mt-1" /><span>{{ l('达到阈值时通知站长（按站长通知偏好投递）', 'Notify the site owner at thresholds (subject to notification preferences)') }}</span></label>
            <p class="text-xs leading-6 text-muted">{{ l('金额来自引擎已有消费记录，不代表银行结算。修改策略后按新版本判断阈值，可能产生新的提醒。', 'Amounts come from engine consumption records, not bank settlement. Editing creates a new policy version and may produce new alerts.') }}</p><Button type="submit" :loading="busy">{{ l('保存预算', 'Save budget') }}</Button>
          </fieldset></form></Card>
          <template v-if="selected">
            <Card class="[&>div]:space-y-4"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="break-words font-semibold">{{ selected.name }}</h2><div class="flex flex-wrap gap-2"><Button variant="outline" size="sm" :disabled="busy" @click="action(loadReport)">{{ l('刷新观测', 'Refresh observations') }}</Button><Button v-if="canManage" variant="outline" size="sm" :disabled="busy" @click="editing = !editing">{{ editing ? l('收起编辑', 'Close editor') : l('编辑策略', 'Edit policy') }}</Button><Button v-if="canManage" variant="outline" size="sm" :disabled="busy || dirty" @click="pause">{{ selected.enabled ? l('暂停策略', 'Pause policy') : l('恢复观测', 'Resume policy') }}</Button></div></div>
              <template v-if="report"><p class="text-sm" :class="['warning', 'exceeded'].includes(report.status) ? 'text-red' : 'text-muted'">{{ label(report.status) }}</p><p class="text-xs text-muted">{{ report.window.from }} — {{ report.window.to }} · {{ label(report.policy.basis) }} · {{ l('策略版本', 'Policy version') }} {{ report.policy.version }}</p>
                <div class="grid gap-3 sm:grid-cols-3"><div class="rounded-lg border border-border p-3"><p class="text-xs text-muted">{{ l('已观测金额', 'Observed amount') }}</p><p class="mt-1 text-xl font-semibold">{{ number(report.observedUsd) }} <small class="text-xs">USD</small></p></div><div class="rounded-lg border border-border p-3"><p class="text-xs text-muted">{{ l('本期预算', 'Period budget') }}</p><p class="mt-1 text-xl font-semibold">{{ number(report.policy.amountUsd) }} <small class="text-xs">USD</small></p></div><div class="rounded-lg border border-border p-3"><p class="text-xs text-muted">{{ l('记录金额覆盖', 'Priced-record coverage') }}</p><p class="mt-1 text-xl font-semibold">{{ report.pricedRecords }}/{{ report.records }}</p></div></div>
                <div v-if="report.observedPercent !== null" class="space-y-1"><div class="h-2 overflow-hidden rounded bg-border" role="progressbar" :aria-label="l('已观测预算比例', 'Observed budget percentage')" :aria-valuenow="progress" aria-valuemin="0" aria-valuemax="100"><div class="h-full bg-accent" :style="{ width: progress + '%' }" /></div><p class="text-xs text-muted">{{ number(report.observedPercent) }}%</p></div>
                <p class="text-xs leading-6 text-muted">{{ l(`本轮读取完整 ${report.completeDays}/${report.window.days.length} 天，未采集 ${report.missingDays} 天。`, `${report.completeDays}/${report.window.days.length} daily scans complete; ${report.missingDays} days missing.`) }} {{ l('低于提醒线只描述已有记录，不能据此保证预算充足。确认提醒也不代表消耗恢复正常。', 'Being below the threshold describes available records only; it does not prove sufficient budget. Acknowledging an alert does not imply recovery.') }}</p>
                <p v-if="report.stale" class="text-sm text-amber">{{ l('今日证据不完整或采集已超过 30 分钟，请先核对采集状态。', 'Today’s evidence is incomplete or over 30 minutes old. Check collection status.') }}</p>
                <div class="flex flex-wrap gap-2"><Button v-if="canManage && selected.enabled" :disabled="busy || dirty" @click="evaluate">{{ l('检查并记录阈值', 'Check and record thresholds') }}</Button><Button variant="outline" :disabled="busy" @click="exportCsv">{{ l('导出每日观测', 'Export daily observations') }}</Button><RouterLink :to="{ path: '/services', query: { site: String(siteId) } }" class="self-center text-sm text-accent">{{ l('查看日志与采集', 'Open logs and collection') }} →</RouterLink></div>
                <details class="rounded border border-border p-3"><summary class="cursor-pointer text-sm">{{ l('查看每日覆盖情况', 'Daily coverage details') }}</summary><div class="mt-3 space-y-2"><div v-for="day in report.days" :key="day.day" class="flex flex-wrap justify-between gap-2 border-t border-border pt-2 text-xs"><span>{{ day.day }} · {{ label(day.scanStatus) }}</span><span>{{ number(day.observedUsd) }} USD · {{ day.pricedRecords }}/{{ day.records }} · {{ day.sourceScope ? label(day.sourceScope) : '—' }}</span></div></div></details>
              </template>
            </Card>
            <Card class="[&>div]:space-y-4"><h2 class="font-semibold">{{ l('阈值事件与复核', 'Threshold events and review') }}</h2><p v-if="!events.length" class="text-sm text-muted">{{ l('暂无阈值事件。', 'No threshold events.') }}</p><article v-for="event in events" :key="event.id" class="space-y-3 rounded-lg border border-border p-3"><p class="text-sm font-medium">{{ event.level }}% · {{ event.evidence.policy.name }} · v{{ event.policyVersion }}</p><p class="text-xs text-muted">{{ event.createdAt }} UTC · {{ event.evidence.window.from }} — {{ event.evidence.window.to }}</p><p class="text-sm">{{ l('当时观测', 'Observed at the time') }} {{ number(event.evidence.observedUsd) }} / {{ number(event.evidence.policy.amountUsd) }} USD · {{ event.evidence.pricedRecords }}/{{ event.evidence.records }} {{ l('条有金额', 'priced records') }}</p><p v-if="event.acknowledgedAt" class="whitespace-pre-wrap break-words text-sm text-muted">{{ l('已复核', 'Reviewed') }} · {{ event.acknowledgement }}</p><form v-else-if="canManage" class="space-y-2" @submit.prevent="acknowledge(event)"><Field :label="l('复核说明', 'Review note')"><textarea v-model="notes[event.id]" class="min-h-20 w-full rounded border border-border bg-bg/60 p-3 text-sm" minlength="5" maxlength="1000" required /></Field><Button type="submit" variant="outline" size="sm" :disabled="busy">{{ l('确认已复核', 'Acknowledge review') }}</Button></form></article><Button v-if="hasMore" variant="outline" :disabled="busy" @click="moreEvents">{{ l('更早事件', 'Older events') }}</Button></Card>
          </template>
        </div>
        <EmptyState v-else :title="l('选择或创建预算', 'Select or create a budget')" :description="l('复用已采集的日志；没有流量或缺失金额时保持未知。', 'Uses collected logs. No traffic or missing amounts remain unknown.')" />
      </div>
    </template>
  </div>
</template>
